import java.util.*;

class SummaryRanges {
    private final TreeMap<Integer, int[]> intervals = new TreeMap<>();

    public SummaryRanges() {
    }

    public void addNum(int value) {
        Map.Entry<Integer, int[]> left = intervals.floorEntry(value);
        if (left != null && left.getValue()[1] >= value) return;
        Map.Entry<Integer, int[]> right = intervals.ceilingEntry(value);
        boolean touchesLeft = left != null && left.getValue()[1] + 1 == value;
        boolean touchesRight = right != null && right.getKey() == value + 1;
        if (touchesLeft && touchesRight) {
            left.getValue()[1] = right.getValue()[1];
            intervals.remove(right.getKey());
        } else if (touchesLeft) {
            left.getValue()[1] = value;
        } else if (touchesRight) {
            intervals.put(value, new int[]{value, right.getValue()[1]});
            intervals.remove(right.getKey());
        } else {
            intervals.put(value, new int[]{value, value});
        }
    }

    public int[][] getIntervals() {
        int[][] result = new int[intervals.size()][2];
        int index = 0;
        for (int[] interval : intervals.values()) {
            result[index++] = new int[]{interval[0], interval[1]};
        }
        return result;
    }
}

import java.util.*;

class SummaryRanges {
    private static final int LIMIT = 10000;
    private final BitSet seen = new BitSet(LIMIT + 1);

    public SummaryRanges() {
    }

    public void addNum(int value) {
        seen.set(value);
    }

    public int[][] getIntervals() {
        List<int[]> answer = new ArrayList<>();
        for (int start = seen.nextSetBit(0); start >= 0; ) {
            int end = Math.min(seen.nextClearBit(start) - 1, LIMIT);
            answer.add(new int[]{start, end});
            if (end == LIMIT) break;
            start = seen.nextSetBit(end + 1);
        }
        return answer.toArray(new int[answer.size()][]);
    }
}

import java.util.*;

class SummaryRanges {
    private final TreeSet<Integer> values = new TreeSet<>();

    public SummaryRanges() {
    }

    public void addNum(int value) {
        values.add(value);
    }

    public int[][] getIntervals() {
        List<int[]> intervals = new ArrayList<>();
        Integer start = null;
        Integer previous = null;
        for (int value : values) {
            if (start == null) {
                start = value;
                previous = value;
            } else if (value == previous + 1) {
                previous = value;
            } else {
                intervals.add(new int[]{start, previous});
                start = value;
                previous = value;
            }
        }
        if (start != null) intervals.add(new int[]{start, previous});
        return intervals.toArray(new int[intervals.size()][]);
    }
}

import java.util.*;

class SummaryRanges {
    private final Set<Integer> seen = new HashSet<>();
    private final Map<Integer, Integer> startToEnd = new HashMap<>();
    private final Map<Integer, Integer> endToStart = new HashMap<>();
    private final TreeSet<Integer> starts = new TreeSet<>();

    public SummaryRanges() {
    }

    public void addNum(int value) {
        if (!seen.add(value)) return;
        int start = value;
        int end = value;
        Integer leftStart = endToStart.remove(value - 1);
        if (leftStart != null) {
            start = leftStart;
            startToEnd.remove(leftStart);
            starts.remove(leftStart);
        }
        Integer rightEnd = startToEnd.remove(value + 1);
        if (rightEnd != null) {
            end = rightEnd;
            endToStart.remove(rightEnd);
            starts.remove(value + 1);
        }
        startToEnd.put(start, end);
        endToStart.put(end, start);
        starts.add(start);
    }

    public int[][] getIntervals() {
        int[][] result = new int[starts.size()][2];
        int index = 0;
        for (int start : starts) {
            result[index++] = new int[]{start, startToEnd.get(start)};
        }
        return result;
    }
}

import java.util.*;

class SummaryRanges {
    private static final int LIMIT = 10000;
    private final boolean[] present = new boolean[LIMIT + 1];
    private final int[] parent = new int[LIMIT + 1];
    private final int[] start = new int[LIMIT + 1];
    private final int[] end = new int[LIMIT + 1];
    private final TreeMap<Integer, Integer> componentByStart = new TreeMap<>();

    public SummaryRanges() {
        for (int i = 0; i <= LIMIT; i++) parent[i] = i;
    }

    public void addNum(int value) {
        if (present[value]) return;
        present[value] = true;
        parent[value] = value;
        start[value] = value;
        end[value] = value;
        componentByStart.put(value, value);
        if (value > 0 && present[value - 1]) union(value, value - 1);
        if (value < LIMIT && present[value + 1]) union(value, value + 1);
    }

    public int[][] getIntervals() {
        int[][] result = new int[componentByStart.size()][2];
        int index = 0;
        for (int root : componentByStart.values()) {
            root = find(root);
            result[index++] = new int[]{start[root], end[root]};
        }
        return result;
    }

    private void union(int a, int b) {
        int rootA = find(a);
        int rootB = find(b);
        if (rootA == rootB) return;
        componentByStart.remove(start[rootA]);
        componentByStart.remove(start[rootB]);
        parent[rootB] = rootA;
        start[rootA] = Math.min(start[rootA], start[rootB]);
        end[rootA] = Math.max(end[rootA], end[rootB]);
        componentByStart.put(start[rootA], rootA);
    }

    private int find(int value) {
        if (parent[value] != value) parent[value] = find(parent[value]);
        return parent[value];
    }
}
